<script setup lang="ts">
import { computed,ref,watch,nextTick,onUnmounted } from 'vue'
import { invoke } from '@tauri-apps/api/core'
import { ChevronDown,Search,Upload,LoaderCircle,Music2,Play,Pause,SkipBack,SkipForward,Heart,Radio,RefreshCw,AudioLines,Languages } from 'lucide-vue-next'
import { parseLyrics,addTranslation,lyricIndex } from './lyrics'
import KaraokeLine from './KaraokeLine.vue'
import { titleAliases,artistAliases } from './music-names'
type Song={id:string;title:string;artist:string;cover?:string;bvid?:string;sourceId?:string;duration?:string;durationMs?:number;customLyrics?:string;customTranslation?:string;customLyricsProvider?:string;lyricOffsetMs?:number;matchScore?:number}
const props=defineProps<{song:Song;elapsed:number;duration:number;playing:boolean;liked:boolean;balanceEnabled:boolean;balanceDb:number;balanceCustomized:boolean;trackGainDb:number;audio?:HTMLAudioElement}>()
const emit=defineEmits<{close:[];toggle:[];previous:[];next:[];like:[];source:[];seek:[seconds:number];lyrics:[text:string,provider?:string];translation:[text:string];offset:[ms:number];balance:[enabled:boolean];balanceDefault:[];trackGain:[db:number]}>()
const text=ref(''),provider=ref(''),busy=ref(false),message=ref(''),instrumental=ref(false),searchOpen=ref(false),lookupTitle=ref(props.song.title),lookupArtist=ref(props.song.artist),scroll=ref<HTMLElement>(),file=ref<HTMLInputElement>(),manualScrollUntil=ref(0)
const translationNotice=ref(''),showTranslation=ref(true),importKind=ref<'lyrics'|'translation'>('lyrics'),clock=ref(props.elapsed)
let generation=0,alive=true,animationFrame=0
const lines=computed(()=>addTranslation(parseLyrics(text.value),props.song.customTranslation||'')),active=computed(()=>lyricIndex(lines.value,clock.value,props.song.lyricOffsetMs||0)),hasWords=computed(()=>lines.value.some(l=>l.words?.length)),hasTranslation=computed(()=>lines.value.some(l=>l.translation?.trim()))
function frame(){if(!alive)return;clock.value=props.audio?.currentTime??props.elapsed;if(props.playing)animationFrame=requestAnimationFrame(frame)}
watch(()=>props.playing,playing=>{cancelAnimationFrame(animationFrame);clock.value=props.elapsed;if(playing)animationFrame=requestAnimationFrame(frame)},{immediate:true})
watch(()=>props.elapsed,value=>{if(!props.playing||!props.audio)clock.value=value})
function chooseFile(kind:'lyrics'|'translation'){importKind.value=kind;file.value?.click()}
const time=(n:number)=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`
async function lookup(custom=false){const run=++generation;busy.value=true;message.value='';text.value='';provider.value='';instrumental.value=false;try{const d=await invoke<{text:string;provider:string;instrumental?:boolean}>('get_lyrics',{title:lookupTitle.value,artist:lookupArtist.value,titleAliases:titleAliases(lookupTitle.value).map(v=>v.text),artistAliases:artistAliases(lookupArtist.value),sourceId:custom?null:props.song.sourceId||null,durationMs:props.song.durationMs||Math.round(props.duration*1000)||null});if(alive&&run===generation){text.value=d.text;provider.value=d.provider;instrumental.value=!!d.instrumental;if(custom&&d.text)emit('lyrics',d.text,d.provider)}}catch(e){if(alive&&run===generation)message.value=String(e)}finally{if(alive&&run===generation)busy.value=false}}
async function scrollToActive(force=false){await nextTick();if(!scroll.value||(!force&&Date.now()<manualScrollUntil.value))return;const line=scroll.value.querySelector<HTMLElement>(`[data-line="${Math.max(0,active.value)}"]`);if(line){const top=line.offsetTop-scroll.value.clientHeight/2+line.clientHeight/2;scroll.value.scrollTo({top,behavior:force?'instant':'smooth'})}}
function follow(){manualScrollUntil.value=0;void scrollToActive(true)}
async function importFile(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];input.value='';if(!f)return;if(f.size>1_000_000){message.value='歌词文件请小于 1 MB';return}const id=props.song.id,kind=importKind.value;try{const bytes=new Uint8Array(await f.arrayBuffer());const raw=f.name.toLowerCase().endsWith('.krc')?await invoke<string>('decode_lyric_file',{bytes:Array.from(bytes)}):new TextDecoder().decode(bytes);if(!alive||props.song.id!==id)return;if(kind==='translation'){const merged=addTranslation(parseLyrics(text.value).map(line=>({...line,translation:undefined})),raw);if(!merged.some(l=>l.translation?.trim())){translationNotice.value='译文未对齐：请导入时间轴一致的 LRC，或行数相同的纯文本译文';return}emit('translation',raw);showTranslation.value=true;translationNotice.value='';message.value='';return}generation++;busy.value=false;instrumental.value=false;text.value=raw;provider.value='导入的歌词';message.value='';emit('lyrics',raw,'导入的歌词')}catch(e){if(alive&&props.song.id===id)message.value=String(e)}}
function gainInput(e:Event){const raw=(e.target as HTMLInputElement).value;if(!raw.trim())return;const value=Number(raw);if(Number.isFinite(value))emit('trackGain',value)}
function offset(e:Event){const value=Number((e.target as HTMLInputElement).value);if(Number.isFinite(value))emit('offset',Math.max(-30000,Math.min(30000,Math.round(value*1000))))}
watch([()=>props.song.id,()=>props.song.customLyrics],()=>{generation++;translationNotice.value='';lookupTitle.value=props.song.title;lookupArtist.value=props.song.artist;manualScrollUntil.value=0;message.value='';if(props.song.customLyrics){text.value=props.song.customLyrics;provider.value=props.song.customLyricsProvider||'导入的歌词';busy.value=false;instrumental.value=false}else void lookup()},{immediate:true})
watch(active,()=>void scrollToActive())
watch(()=>props.song.lyricOffsetMs,()=>void scrollToActive(true))
onUnmounted(()=>{alive=false;generation++;cancelAnimationFrame(animationFrame)})
</script>
<template>
 <section class="track-details" aria-label="歌曲详情与歌词">
  <header class="details-header"><span><AudioLines :size="17"/> 正在聆听</span><button class="icon-btn" title="收起歌曲详情" @click="emit('close')"><ChevronDown :size="25"/></button></header>
  <div class="details-body"><div class="details-info"><div class="details-cover"><img v-if="song.cover" :src="song.cover" referrerpolicy="no-referrer"/><Music2 v-else :size="75"/></div><h1>{{song.title}}</h1><p class="details-artist">{{song.artist||'未知歌手'}}</p><div class="details-tags"><span>{{song.bvid?'B 站音源':'本地音乐'}}</span><span v-if="song.matchScore!==undefined">匹配评分 {{song.matchScore}}</span><span>{{time(duration)}}</span></div><div class="details-controls"><button class="icon-btn" title="上一首" @click="emit('previous')"><SkipBack :size="24"/></button><button class="play-main" :title="playing?'暂停':'播放'" @click="emit('toggle')"><Pause v-if="playing" :size="24" fill="currentColor"/><Play v-else :size="24" fill="currentColor"/></button><button class="icon-btn" title="下一首" @click="emit('next')"><SkipForward :size="24"/></button><button :class="['icon-btn',{liked}]" title="收藏" @click="emit('like')"><Heart :size="21" :fill="liked?'currentColor':'none'"/></button></div><button v-if="song.bvid" class="text-btn" @click="emit('source')"><Radio :size="16"/>更换歌源</button><label class="balance-toggle"><input type="checkbox" :checked="balanceEnabled" @change="emit('balance',($event.target as HTMLInputElement).checked)"/><span>这首歌的音量平衡<small>{{balanceEnabled?`已开启 · ${balanceDb>0?'+':''}${balanceDb.toFixed(1)} dB`:'已关闭'}}</small></span></label><div class="balance-origin"><span>{{balanceCustomized?'已自定义 · 不受全局开关影响':'跟随全局音量平衡'}}</span><button v-if="balanceCustomized" class="text-btn" @click="emit('balanceDefault')">跟随全局</button></div><div class="track-gain-control"><label for="track-gain">这首歌的音量 <strong>{{trackGainDb>0?'+':''}}{{trackGainDb.toFixed(1)}} dB</strong></label><div><input id="track-gain" type="range" min="-12" max="12" step="0.5" :value="trackGainDb" aria-label="这首歌的音量增益" @input="gainInput"/><input type="number" min="-12" max="12" step="0.5" :value="trackGainDb" aria-label="这首歌的音量增益分贝" @input="gainInput"/></div><p><span>仅对这首歌生效 · 自动保存</span><button class="text-btn" :disabled="trackGainDb===0" @click="emit('trackGain',0)">恢复 0 dB</button></p></div></div>
   <div class="details-lyrics"><div class="lyrics-heading"><h2>歌词</h2><span>{{busy?'正在匹配…':lines.length?(hasWords?'逐字同步':'逐行同步'):text?'纯文本':instrumental?'纯音乐':'未匹配'}}</span><button :class="['text-btn','translation-toggle',{enabled:showTranslation&&hasTranslation}]" :aria-pressed="showTranslation&&hasTranslation" :title="hasTranslation?'显示或隐藏译文':'导入中文译文'" @click="hasTranslation?showTranslation=!showTranslation:chooseFile('translation')"><Languages :size="16"/>{{hasTranslation?(showTranslation?'译文开':'译文关'):'导入译文'}}</button><button class="icon-btn" title="调整歌词匹配" @click="searchOpen=!searchOpen"><Search :size="17"/></button><button class="icon-btn" title="导入 KRC、LRC 或 TXT 歌词" @click="chooseFile('lyrics')"><Upload :size="17"/></button></div>
    <p v-if="translationNotice" class="translation-notice" role="status">{{translationNotice}}</p><form v-if="searchOpen" class="lyrics-search" @submit.prevent="lookup(true)"><input v-model="lookupTitle" class="field" placeholder="歌名" aria-label="歌词匹配歌名"/><input v-model="lookupArtist" class="field" placeholder="歌手" aria-label="歌词匹配歌手"/><button class="secondary" :disabled="busy||!lookupTitle.trim()">重新匹配</button><button type="button" class="secondary" @click="chooseFile('translation')">导入译文</button></form>
    <div v-if="busy" class="lyrics-placeholder"><LoaderCircle class="spin" :size="31"/><h3>寻找这首歌的文字</h3><p>正在核对歌名、歌手与时长</p></div>
    <div v-else-if="message" class="lyrics-placeholder"><Music2 :size="32"/><p role="status">{{message}}</p><button class="secondary" @click="lookup()"><RefreshCw :size="15"/>重试匹配</button><button class="text-btn" @click="chooseFile('lyrics')">导入本地歌词</button></div>
    <div v-else-if="instrumental" class="lyrics-placeholder"><AudioLines :size="35"/><h3>纯音乐，请欣赏</h3><button class="text-btn" @click="chooseFile('lyrics')">有歌词？手动导入</button></div>
    <div v-else-if="lines.length" ref="scroll" class="lyric-scroll" @wheel="manualScrollUntil=Date.now()+5000" @touchstart="manualScrollUntil=Date.now()+5000"><div class="lyric-spacer"/><button v-for="(line,i) in lines" :key="i" :data-line="i" :class="['lyric-line',{current:i===active,past:i<active}]" @click="emit('seek',Math.max(0,line.time+(song.lyricOffsetMs||0)/1000));follow()"><KaraokeLine :line="line" :position="i===active?clock:0" :offset-ms="song.lyricOffsetMs||0" :active="i===active" :past="i<active" :translation="showTranslation"/></button><div class="lyric-spacer"/></div>
    <div v-else class="plain-lyrics">{{text||'暂无歌词'}}</div>
    <footer class="lyrics-footer"><span>{{provider||'歌词匹配'}}<small v-if="lines.length&&!hasWords" class="lyric-capability">当前来源只有逐行时间轴</small><small v-if="lines.length&&!hasTranslation" class="lyric-capability">暂无现成译文，可导入中文 LRC</small></span><button v-if="lines.length" class="text-btn" @click="follow">回到当前歌词</button><label v-if="lines.length">歌词延后 <input type="number" :value="(song.lyricOffsetMs||0)/1000" min="-30" max="30" step="0.1" aria-label="歌词时间偏移秒" @change="offset"/> 秒</label></footer>
   </div>
  </div><input ref="file" type="file" hidden accept=".krc,.lrc,.txt" @change="importFile"/>
 </section>
</template>
